import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D1.3 · MVP 收口","description":"Hearth D1.3 开发增量：Hearth MVP-1 可用：创建、查看、取消、重试、审批演练、取回产物和恢复都在浏览器中完成。","frontmatter":{"title":"D1.3 · MVP 收口","description":"Hearth D1.3 开发增量：Hearth MVP-1 可用：创建、查看、取消、重试、审批演练、取回产物和恢复都在浏览器中完成。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/d1-3.md","filePath":"delivery/stage-1/d1-3.md","lastUpdated":1793761874000}'),r={name:"delivery/stage-1/d1-3.md"};function s(h,a,d,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 1 · D1.3 · 3 / 6</p><h1 id="d1-3-·-mvp-收口" tabindex="-1">D1.3 · MVP 收口 <a class="header-anchor" href="#d1-3-·-mvp-收口" aria-label="Permalink to &quot;D1.3 · MVP 收口&quot;">​</a></h1><p class="lead">把已经跑通的任务路径收口成一个可以每天使用的最小产品，而不是一个只能演示的后端切片。</p><p class="page-meta">STAGE 1 · D1.3 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>Hearth MVP-1 可用：创建、查看、取消、重试、审批演练、取回产物和恢复都在浏览器中完成。</div><div><strong>完成门槛</strong>至少 5 个代表性真实任务通过；其中 3 个重复运行稳定；四个关键中断点均可恢复；用户明确愿意继续使用；没有未受控真实副作用。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>Hearth MVP-1 可用：创建、查看、取消、重试、审批演练、取回产物和恢复都在浏览器中完成。</p><p>Stage 1 的顺序是先有真实短闭环，再有安全副作用，最后扩大任务族和恢复覆盖；不能在空内核上先堆模块。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 0 的 12 个任务、原型、协议、评测与安全基线已经评审通过。</li><li>默认任务楔子是研究/文档整理；如果首位用户更依赖代码任务，可以替换楔子，但纵向结构不能改变。</li><li>本地开发环境、SQLite、可隔离 workspace 和 Web 构建链路可用。</li><li>D1.2 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-mvp-任务全生命周期" tabindex="-1">01 · MVP 任务全生命周期 <a class="header-anchor" href="#_01-·-mvp-任务全生命周期" aria-label="Permalink to &quot;01 · MVP 任务全生命周期&quot;">​</a></h3><p>补齐持久 Run、详情时间线、取消、重试、失败页、产物中心和预算上限。所有动作在 Web 中完成，用户不需要打开终端。</p><h3 id="_02-·-失败解释与恢复入口" tabindex="-1">02 · 失败解释与恢复入口 <a class="header-anchor" href="#_02-·-失败解释与恢复入口" aria-label="Permalink to &quot;02 · 失败解释与恢复入口&quot;">​</a></h3><p>每个失败显示发生了什么、影响范围、是否可重试、是否会重复副作用和下一步。无法自动恢复时明确转人工，而不是继续转圈。</p><h3 id="_03-·-练习-effect-的审批闭环" tabindex="-1">03 · 练习 Effect 的审批闭环 <a class="header-anchor" href="#_03-·-练习-effect-的审批闭环" aria-label="Permalink to &quot;03 · 练习 Effect 的审批闭环&quot;">​</a></h3><p>用本地测试服务或测试账户演示 Effect Preview、批准、拒绝和 Receipt。审批必须绑定动作、参数、范围和过期时间。</p><h3 id="_04-·-10-个真实任务与体验收口" tabindex="-1">04 · 10 个真实任务与体验收口 <a class="header-anchor" href="#_04-·-10-个真实任务与体验收口" aria-label="Permalink to &quot;04 · 10 个真实任务与体验收口&quot;">​</a></h3><p>让首位用户完成至少 10 个真实任务，记录成功率、人工分钟、Token、失败与恢复；修复阻塞主路径的文案、布局和状态歧义。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd</code> — 单进程常驻、Gateway、Control、Harness 与 SSE</li><li><code>packages/eventlog</code> — SQLite WAL、事件、投影、migration 与 replay</li><li><code>packages/harness</code> — Ticket、Run、lease、outbox、恢复与死信</li><li><code>packages/executors/codex</code> — Codex adapter、workspace 与结构化输出</li><li><code>packages/policy</code> — Policy、Mandate、Approval 与风险等级</li><li><code>packages/artifacts</code> — 内容寻址产物、哈希、版本与验证器</li><li><code>apps/web</code> — 任务卡、详情/时间线、审批、产物与恢复</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Run</code></td><td>runId、ticketId、state、checkpoint、budget、terminalReason；一次执行尝试只能有一个终态。</td></tr><tr><td><code>Ticket / Lease</code></td><td>owner、scope、expiresAt、fencingToken；同一 Ticket 同时最多一个有效写者。</td></tr><tr><td><code>TaskPack</code></td><td>objective、inputs、constraints、outputSchema、acceptance、budget、permissions；执行器只在该包内工作。</td></tr><tr><td><code>Effect / Receipt</code></td><td>effectIntent、approvalId、idempotencyKey、receipt、reconciliation；不确定结果先对账，不盲目重试。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：hearthd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 同时启动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:fault：kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9、断网、超时、重复投递</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e：创建→取消→重试→审批→产物→恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:mvp：10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个真实任务与基线对比</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-1/d1-3.html">D1.3 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：MVP 任务全生命周期、失败解释与恢复入口、练习 Effect 的审批闭环、10 个真实任务与体验收口。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“进程崩溃或重启”。页面必须显示“任务详情显示最后已知状态、未完成步骤和“继续/取消/重试”。”，然后按“从 Event Log 重放并重新领取 lease，禁止静默丢弃任务。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：至少 5 个代表性真实任务通过；其中 3 个重复运行稳定；四个关键中断点均可恢复；用户明确愿意继续使用；没有未受控真实副作用。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>MVP-1 验收记录</li><li>取消/重试/恢复演示</li><li>练习审批与回执</li><li>5 个真实任务结果</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 至少 5 个代表性真实任务通过；其中 3 个重复运行稳定；四个关键中断点均可恢复；用户明确愿意继续使用；没有未受控真实副作用。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>进程崩溃或重启</td><td>任务详情显示最后已知状态、未完成步骤和“继续/取消/重试”。</td><td>从 Event Log 重放并重新领取 lease，禁止静默丢弃任务。</td></tr><tr><td>外部动作重复</td><td>系统显示“正在对账”，不生成第二个成功回执。</td><td>按幂等键查询 sink，确认已完成后补写 Receipt 或走补偿。</td></tr><tr><td>副作用结果不确定</td><td>任务进入“等待确认”，隐藏自动重试按钮。</td><td>先查询外部系统或人工核对，再决定重试、补偿或关闭。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不允许只靠 CLI、日志或数据库证明 MVP 可用。</li><li>不在恢复与审批未稳定前扩大任务族。</li><li>不把永久 mock 结果当成真实执行。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/durable-execution.html">持久执行与恢复</a></li><li><a href="/hearth-os/architecture/executor-model.html">执行器模型</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全与副作用</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-1/d1-4.html">D1.4 · 副作用安全骨架</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const u=e(r,[["render",s]]);export{k as __pageData,u as default};
